// === 설정 ===
const SECRET = 'CHANGE_ME_SAME_AS_N8N_SECRET';      // /etc/jrdesk-monitor.env 의 N8N_SECRET 과 동일
const DEVICE_NAMES = { /* '123456789': '서울역-컨트롤러PC' */ };  // ID → 현장명 매핑
const MY_IPS = [];   // 알림 생략할 내 IP (빈 배열 = 전부 알림)

const out = [];
const store = $getWorkflowStaticData('global');
store.events = store.events || [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  if (h['x-jrdesk-secret'] !== SECRET) continue;          // 인증 실패 → 무시
  const e = item.json.body || {};
  const kst = new Date(e.ts || Date.now()).toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' });
  const dev = e.device_id ? `${e.device_id}${DEVICE_NAMES[e.device_id] ? ' (' + DEVICE_NAMES[e.device_id] + ')' : ''}` : '-';
  const label = {
    invalid_key: '🔴 잘못된 키 접속 시도 (외부/스캔 의심)',
    connect_attempt: '🟡 원격 접속 시도',
    relay_start: '🟢 중계 세션 시작',
    relay_end: '⚪ 중계 세션 종료',
    blocked: '⛔ IP 자동 차단 (방화벽)',
    block_failed: '⚠️ IP 자동 차단 실패',
  }[e.type] || ('ℹ️ ' + e.type);
  let text = `[JRDesk] ${label}\n시각: ${kst} (KST)\nIP: ${e.ip || '-'}\n대상 ID: ${dev}\n서버: ${e.source || '-'}`;
  if (e.duration_sec != null) text += `\n지속: ${Math.floor(e.duration_sec / 60)}분 ${e.duration_sec % 60}초`;
  if (e.ttl_sec != null) text += `\n차단 기간: ${Math.round(e.ttl_sec / 3600)}시간 · 기준 ${Math.round((e.window_sec||0) / 3600)}시간 내 ${e.count}회`;
  store.events.push({ ts: e.ts, kst, type: e.type, ip: e.ip, device: dev, dur: e.duration_sec ?? null });
  if (store.events.length > 5000) store.events = store.events.slice(-5000);
  if (MY_IPS.includes(e.ip)) continue;                     // 기록은 하되 알림 생략
  out.push({ json: { text } });
}
return out;

const store = $getWorkflowStaticData('global');
const all = store.events || [];
const ymd = d => d.toLocaleDateString('sv-SE', { timeZone: 'Asia/Seoul' }); // YYYY-MM-DD
const y = new Date(Date.now() - 24 * 3600 * 1000);
const day = ymd(y);
const evs = all.filter(e => ymd(new Date(e.ts)) === day);
store.events = all.filter(e => ymd(new Date(e.ts)) > day);   // 기록한 날짜 이전 이벤트 정리
const cnt = t => evs.filter(e => e.type === t).length;
const rows = evs.map(e => `| ${e.kst} | ${e.type} | ${e.ip || '-'} | ${e.device} | ${e.dur ?? ''} |`).join('\n');
const md = `---
title: JRDesk 접속 로그 ${day}
date: ${day}
tags: [jrdesk, 보안, 접속로그]
source: n8n jrdesk-events
---
# JRDesk 접속 로그 ${day}

관련: [[JRDesk]] · [[임팩트럼 허브]]

## 요약
- 🔴 잘못된 키 시도: ${cnt('invalid_key')}
- 🟡 접속 시도: ${cnt('connect_attempt')}
- 🟢 중계 세션: ${cnt('relay_start')}
- 총 이벤트: ${evs.length}

## 상세
| 시각(KST) | 유형 | IP | 대상 ID | 지속(초) |
|---|---|---|---|---|
${rows || '| - | 이벤트 없음 | - | - | - |'}
`;
return [{ json: { fileName: `JRDesk_접속로그_${day}.md`, count: evs.length },
          binary: { data: { data: Buffer.from(md, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: `JRDesk_접속로그_${day}.md` } } }];
